Item.method_code:
const [{ getResource, odataFetch }, { confirm }, { CUIError }] =
	await Promise.all([
		import('../jsBundles/core.es.js'),
		import('../jsBundles/dialogs.es.js'),
		import('../jsBundles/cui.es.js')
	]);

const dialogSettings = {
	title: getResource('dialog.reset_to_original_form_design.title'),
	okButtonText: getResource('common.reset'),
	okButtonModifier: 'aras-button_secondary',
	image: '../images/Delete.svg'
};
const dialogMessage = getResource(
	'dialog.reset_to_original_form_design.message'
);

const result = await confirm(dialogMessage, dialogSettings);
if (result !== 'ok') return;

window.formEditorLayout.actions.toggleSpinner(true);

try {
	await odataFetch('method.cuiform_ResetUnsealedForms', {
		method: 'POST',
		body: JSON.stringify({ id: options.itemId })
	});

window.layout.observer.notify('ResetToOriginalFormDesign');
} catch (error) {
	throw new CUIError(error.message)
}
finally {
	window.formEditorLayout.actions.toggleSpinner(false)
};
